struct Listing { address seller; uint256 price; }

// nftContract => tokenId => active listing
mapping(address => mapping(uint256 => Listing)) public listings;

event Listed(address nft, uint256 id, address seller, uint256 price);
event Sale(address nft, uint256 id, address buyer, uint256 price);
event Cancelled(address nft, uint256 id);

function listItem(address nft, uint256 tokenId, uint256 price) external {
    require(price > 0, "price must be > 0");
    require(IERC721(nft).ownerOf(tokenId) == msg.sender, "not owner");
    require(
        IERC721(nft).isApprovedForAll(msg.sender, address(this)) ||
        IERC721(nft).getApproved(tokenId) == address(this),
        "marketplace not approved"
    );
    listings[nft][tokenId] = Listing(msg.sender, price);
    emit Listed(nft, tokenId, msg.sender, price);
}

function buyItem(address nft, uint256 tokenId) external payable nonReentrant {
    Listing memory listing = listings[nft][tokenId];
    require(listing.price > 0, "not listed");
    require(msg.value == listing.price, "wrong price");

    delete listings[nft][tokenId];           // state cleared FIRST

    (address receiver, uint256 royalty) =
        _royaltyFor(nft, tokenId, listing.price);
    IERC721(nft).safeTransferFrom(listing.seller, msg.sender, tokenId);
    if (royalty > 0) _pay(receiver, royalty);
    _pay(listing.seller, listing.price - royalty);
}

function _royaltyFor(address nft, uint256 id, uint256 price)
    private view returns (address, uint256)
{
    if (!IERC2981(nft).supportsInterface(type(IERC2981).interfaceId)) {
        return (address(0), 0);   // collection has no royalty standard
    }
    return IERC2981(nft).royaltyInfo(id, price);
}
